head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.vScrenID = 'ULDBNS05100.xml';
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명  	 : fn_list_sync
 * 설명       : 일괄상장매출액미통보 내역 조회
 ***********************************************/
scwin.fn_list_sync = function() {
    var dsNm = 'BNS_PACK_UN_SALES_LIST';
    var qryId = 'lds.stf.bnspack.select.listSalesNonNoti';
    var param = '&{P}V_ISUR_CD=' + $c.stf.getObjectValue(txb_IsurNm);
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List, dsNm, qryId, param);
    $c.cm.ShowWin(grd_List);
};


/********************************************** 
 * 함수명   : fn_GetParIsurCd
 * 설명       : 발행기관 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsurCd = function(arrPar) {
    arrPar[0] = {
        ISUR_CD: $c.stf.getObjectValue(txb_IsurNm)
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParIsurCd
 * 설명       : 발행기관 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParIsurCd = function(arrPar) {
    $c.stf.setObjectValue(txb_IsurNm, arrPar[0].ISUR_NM);
};


/********************************************** 
 * 함수명   : fn_ShowIsur
 * 설명       : 발행기관 팝업을 보여준다.
 ***********************************************/
scwin.fn_ShowIsur = function(txb_IsurNm) {
    scwin.fn_GetPar = fn_GetParIsurCd;
    scwin.fn_SetPar = fn_SetParIsurCd;
    $c.bns.fn_PopIsurSearch(lbl_IsurNm);
};


/********************************************** 
 * 함수명   : fn_GetParIsuDelInfo
 * 설명       : 종목상세 목록 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsuDelInfo = function(arrPar) {
    arrPar[0] = {
        STD_CD: dts_List.getCellData(dts_List.getRowPosition(), "ISU_CD")
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.bns.BnsPanelToGroupBox(pnl_Search);
    // 목록 조회
    scwin.fn_list_sync();
};
scwin.dts_List_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.txb_IsurNm_onkeypress = function() {
    if (window.event.keyCode == 13) scwin.fn_list_sync();
};
scwin.img_com_srch_onclick = function() {
    scwin.fn_ShowIsur(txb_IsurNm);
};
scwin.grd_List_OnClick = function(row, colid) {
    if (row > 0) {
        scwin.fn_GetPar = fn_GetParIsuDelInfo;
        $c.bns.fn_PopIsuDetail(lbl_IsurNm);
    }
};
scwin.btn_ToExcel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07, '');
    var fileNm = $c.session.getExcelDownPath() + $c.ut.cGetToday("yyyymmddhhmmss") + "_일괄상장 매출액 미통보 종목.xls";
    $c.data.downloadGridViewExcel(grd_List, "일괄상장 매출액 미통보", "", "8");
};
